  process(src, path) {
    if (path.endsWith('__tests__/MultiRequire.js')) {
      // exit early for multi-require as we explicitly want to have several instances
      return { code: src };
    }

    if (path.endsWith('.ts') || path.endsWith('.tsx')) {
      return { code: transpileTypeScript(src, path) };
    }

    return transpileJavaScript(src, path);
  },

  getCacheKey() {
    // ignore cache, as there is a conflict between rollup compile and jest preprocessor.
    return Date.now().toString();
  },
};
const path = require('path');
const pkg = require('../package.json');

module.exports = (request, options) => {
  if (request === 'immutable') {
    if (process.env.CI) {
      // In CI environment, test the real built file to be sure that the build is not broken
      return path.resolve(options.rootDir, pkg.main);
    }

    // In development mode, we want sourcemaps, live reload, etc., so point to the src/ directory
    return `${options.rootDir}/src/Immutable.js`;
  }

